define(["jquery"],function($){"use strict";function init(payload){if(!payload||!payload.policies){return}var gatekeepers=[];var context={cmid:payload.cmid,attemptid:payload.attemptid};function runGatekeepers(){var deferred=$.Deferred();var index=0;function next(){if(index>=gatekeepers.length){deferred.resolve(true);return}var fn=gatekeepers[index++];var result=true;try{result=fn(context)}catch(e){deferred.resolve(false);return}if(result&&typeof result.then==="function"){result.then(function(ok){if(ok===false){deferred.resolve(false)}else{next()}}).fail(function(){deferred.resolve(false)})}else if(result===false){deferred.resolve(false)}else{next()}}next();return deferred.promise()}context.api={registerGatekeeper:function(fn){if(typeof fn==="function"){gatekeepers.push(fn)}},runGatekeepers:runGatekeepers};payload.policies.forEach(function(p){if(!p.amd){return}requirejs([p.amd],function(mod){if(mod&&typeof mod.init==="function"){mod.init(context,p.config||{})}})})}return{init:init}});